import{_ as e,r as s,o,c,e as n,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"更新部件 - October CMS - 3.x","titleTemplate":false,"description":"了解更多关于动态更新内容的信息。","frontmatter":{"subtitle":"了解更多关于动态更新内容的信息。"},"headers":[{"level":2,"title":"拉取部件更新","slug":"拉取部件更新","link":"#拉取部件更新","children":[{"level":3,"title":"自更新部件","slug":"自更新部件","link":"#自更新部件","children":[]},{"level":3,"title":"全局部件更新","slug":"全局部件更新","link":"#全局部件更新","children":[]}]},{"level":2,"title":"更新定义","slug":"更新定义","link":"#更新定义","children":[{"level":3,"title":"追加和前置内容","slug":"追加和前置内容","link":"#追加和前置内容","children":[]},{"level":3,"title":"使用自定义 HTML 选择器","slug":"使用自定义-html-选择器","link":"#使用自定义-html-选择器","children":[]}]},{"level":2,"title":"推送部件更新","slug":"推送部件更新","link":"#推送部件更新","children":[]},{"level":2,"title":"向部件传递变量","slug":"向部件传递变量","link":"#向部件传递变量","children":[]}],"relativePath":"3.x/zh-cn/cms/ajax/update-partials.md","filePath":"3.x/zh-cn/cms/ajax/update-partials.md"}'),u={name:"3.x/zh-cn/cms/ajax/update-partials.md"};function i(k,a,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[n(t),a[0]||(a[0]=l("h1",null,"更新部件",-1)),n(p),a[1]||(a[1]=r(`<p>当处理程序执行时，它可以准备在页面上更新的部件，通过推送或拉取方式，并且可以使用提供的变量进行渲染。</p><h2 id="拉取部件更新"><a href="#拉取部件更新" class="header-anchor">#</a> 拉取部件更新</h2><p>客户端浏览器在执行 AJAX 请求时可以请求从服务器更新部件，这被视为<em>拉取内容更新</em>。</p><p>使用 <a href="./../../markup/tag/partial.html"><code>{% partial %}</code> 标签</a>，以下代码在调用 <code>onRefreshTime</code> <a href="./handlers.html">事件处理程序</a>时，在页面上的 <code>#myDiv</code> 元素内渲染 <strong>mytime</strong> 部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./attributes-api.html">数据属性 API</a> 使用 <code>data-request-update</code> 属性。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mytime: &#39;#myDiv&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a href="./javascript-api.html">JavaScript API</a> 使用 <code>update</code> 配置选项：</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token comment">// JavaScript API</span>
oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;#mybutton&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;onRefreshTime&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">mytime</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="自更新部件"><a href="#自更新部件" class="header-anchor">#</a> 自更新部件</h3><p><a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> 标签</a>专门用于渲染 AJAX 部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>使用此标签时，内容会自动包装在容器中，因此您只需通过部件名称即可更新它。只需传递 <code>true</code> 值而非容器选择器即可。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mytime: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>您也可以使用部件名称 <code>_self</code> 从部件自身内部更新自己。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">_self</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>请参阅 <a href="./../../markup/tag/ajax-partial.html">AJAX 部件 Twig 标签文章</a>了解更多关于 <code>{% ajaxPartial %}</code> 标签的信息。</p></div><h3 id="全局部件更新"><a href="#全局部件更新" class="header-anchor">#</a> 全局部件更新</h3><p>在某些情况下，例如<a href="./../../cms/features/flash-messages.html">闪存消息</a>，您可能希望在每个响应中包含特定的部件更新。要将更新定义与每个 AJAX 请求合并，请在页面的 head 部分添加 <code>ajax-request-update</code> meta 标签，并将 content 属性设置为更新定义。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ajax-request-update<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ flash-messages: true }<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="更新定义"><a href="#更新定义" class="header-anchor">#</a> 更新定义</h2><p>应更新内容的定义以类似 JSON 的对象格式指定，其中：</p><ul><li>左侧（键）是<strong>部件名称</strong></li><li>右侧（值）是要更新的<strong>目标元素</strong></li></ul><p>以下内容将请求使用 <strong>mypartial</strong> 的内容更新 <code>#myDiv</code> 元素。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">mypartial</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>选择器必须以 <code>#</code> 或 <code>.</code> 字符开头才有效。</p></div><p>多个部件用逗号分隔。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token literal-property property">firstpartial</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">secondpartial</span><span class="token operator">:</span> <span class="token string">&#39;#otherDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>如果部件名称包含斜杠或连字符，则需要用引号将左侧括起来。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/mypartial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span><span class="token punctuation">,</span> <span class="token string-property property">&#39;my-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>目标元素始终在右侧，因为在 JavaScript 中它也可以是 HTML 元素。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/mypartial&#39;</span><span class="token operator">:</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;myDiv&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
</code></pre></div><h3 id="追加和前置内容"><a href="#追加和前置内容" class="header-anchor">#</a> 追加和前置内容</h3><p>如果选择器字符串前面加上 <code>@</code> 符号，从服务器接收到的内容将被追加到元素中，而不是替换现有内容。</p><p>如果选择器字符串前面加上 <code>^</code> 符号，内容将被前置。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/append-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;@#myDiv&#39;</span> <span class="token punctuation">}</span>

<span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/prepend-partial&#39;</span><span class="token operator">:</span> <span class="token string">&#39;^#myDiv&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><p>或者，您可以在目标元素上添加 <code>data-ajax-update-mode</code> 属性。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-ajax-update-mode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>append<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-ajax-update-mode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>prepend<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="使用自定义-html-选择器"><a href="#使用自定义-html-选择器" class="header-anchor">#</a> 使用自定义 HTML 选择器</h3><p>如果选择器字符串以 <code>=</code> 符号开头，则可以使用任何自定义 HTML 选择器来定位元素。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token punctuation">{</span> <span class="token string-property property">&#39;folder/append&#39;</span><span class="token operator">:</span> <span class="token string">&#39;=[data-field-name=&quot;address&quot;]&#39;</span> <span class="token punctuation">}</span>
</code></pre></div><h2 id="推送部件更新"><a href="#推送部件更新" class="header-anchor">#</a> 推送部件更新</h2><p>相比之下，<a href="./handlers.html">AJAX 处理程序</a>可以从服务器端向客户端浏览器推送内容更新。要推送更新，处理程序返回一个数组，其中键是要更新的 HTML 元素（使用简单的 CSS 选择器），值是要更新的内容。</p><div class="custom-block aside"><p>键名必须以标识符 <code>#</code> 或类 <code>.</code> 字符开头才能触发内容更新。</p></div><p>以下示例将使用 <strong>mypartial</strong> 部件中的内容更新页面上 id 为 <strong>myDiv</strong> 的元素。<code>onRefreshTime</code> 处理程序调用 <code>renderPartial</code> 方法在 PHP 中渲染部件内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRefreshTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#myDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypartial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="向部件传递变量"><a href="#向部件传递变量" class="header-anchor">#</a> 向部件传递变量</h2><p>根据执行上下文的不同，<a href="./handlers.html">AJAX 事件处理程序</a>以不同的方式向部件提供变量。</p><ul><li>在页面或布局的 <a href="./../themes/themes.html">PHP 代码部分</a>中使用 <code>$this[]</code>。</li><li>在<a href="./../themes/components.html">组件类</a>中使用 <code>$this-&gt;page[]</code>。</li><li>在<a href="./../../extend/system/controllers.html">后端区域</a>中使用 <code>$this-&gt;vars[]</code>。</li></ul><p>以下示例将为每个上下文向部件提供 <strong>result</strong> 变量：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// From page or layout PHP code section</span>
<span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a component class</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a backend controller or widget</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>然后可以在部件中使用 Twig 访问此值：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Hello world! --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div>`,53))])}const f=e(u,[["render",i]]);export{y as __pageData,f as default};
